{"cards": [{"node_code": "N_170daf1f5b8524e8", "definition": "依据船体主要建造材料（如木材、金属、水泥、复合材料等）对船舶进行的分类体系，涵盖各类材料船舶的结构特征、适用场景及典型代表。", "boundary": "本节点聚焦于“材料”这一单一分类维度。边界在于区分“材料分类”与“用途/动力/结构分类”：若内容侧重船舶的运输功能（如货船），归入“运输船”；若侧重动力源（如核动力），归入“船舶：按动力分”。本节点收录的是基于材料属性的类型学描述，而非材料本身的制造工艺或力学性能研究。", "includes": ["木船、木铁船、水泥船、金属船、塑料/玻璃钢船、橡胶/皮船及混合材料船的类型定义与特征", "不同材料船舶在耐腐蚀性、强度、成本等方面的对比及典型应用实例"], "excludes": ["船舶材料的具体加工工艺、焊接技术或材料力学实验", "以用途（如渔船、军舰）或动力（如蒸汽、电力）为主要分类依据的船舶内容"], "sibling_distinctions": [{"other_code": "N_8daf0804b3fe0843", "rule": "区分依据为分类维度：本节点按“材料”划分（如钢船、木船）；兄弟节点按“动力”划分（如核动力、内燃机）。"}, {"other_code": "N_99dbe341a0a481fd", "rule": "区分依据为分类维度：本节点按“材料”划分；兄弟节点按“船体结构”划分（如双体、单体）。"}], "cross_boundary_rule": "若内容同时涉及材料特性与船体结构（如玻璃钢双体船），主挂载依据内容侧重点：侧重材料属性归本节点，侧重结构形式归“船舶：按船体结构分”。"}, {"node_code": "N_24f79f9d6d4ff534", "definition": "依据船舶在水中的航行状态、浮力原理及运动方式（如排水、滑行、气垫、水翼、潜水等）对船舶进行的分类体系，涵盖各类航行状态船舶的原理与特征。", "boundary": "本节点聚焦于“航行状态/运动方式”这一分类维度。边界在于区分“航行状态”与“用途/材料/动力分类”：若内容侧重船舶的载货或载客功能，归入“运输船”；若侧重船体材质，归入“船舶：按材料分”。本节点收录的是基于流体动力学状态（如是否离开水面、是否在水下）的类型学描述，而非具体的推进器设计或导航技术。", "includes": ["潜水船、滑行艇、冲翼艇、气垫船、水翼船等基于特殊航行状态的船舶类型定义与特征", "不同航行状态（排水、半滑行、全滑行、气垫、水翼）的物理原理简述及典型代表"], "excludes": ["船舶推进系统（螺旋桨、喷水推进）的具体设计与制造", "船舶的导航、通信或驾驶操作技术"], "sibling_distinctions": [{"other_code": "N_8daf0804b3fe0843", "rule": "区分依据为分类维度：本节点按“航行状态”划分（如气垫船、水翼船）；兄弟节点按“动力”划分（如核动力、柴油机）。"}, {"other_code": "N_99dbe341a0a481fd", "rule": "区分依据为分类维度：本节点按“航行状态”划分；兄弟节点按“船体结构”划分（如双体船）。"}], "cross_boundary_rule": "若内容涉及特定航行状态的船舶（如气垫船），主挂载本节点；若深入探讨该船型的动力配置（如燃气轮机），可关联“船舶：按动力分”，但主挂载仍为本节点。"}, {"node_code": "N_99dbe341a0a481fd", "definition": "依据船体结构形式（如单体、双体、多体、箱型等）对船舶进行的分类体系，重点涵盖双体船、多体船等结构类型及其水动力特性与功能定位。", "boundary": "本节点聚焦于“船体结构”这一分类维度。边界在于区分“结构分类”与“用途/材料/动力分类”：若内容侧重船舶的军事或民用用途，归入相应用途节点；若侧重船体材质，归入“船舶：按材料分”。本节点收录的是基于船体几何形态和结构布局的类型学描述，而非船体结构的强度计算或详细设计图纸。", "includes": ["双体船、多体船（三体、四体等）的结构特征、稳定性优势及典型应用", "其他特殊船体结构（如箱型船、半潜式平台船体）的分类与描述"], "excludes": ["船体结构的有限元分析、强度校核及详细结构设计", "船舶的总体布置、舱室规划或内部设备配置"], "sibling_distinctions": [{"other_code": "N_170daf1f5b8524e8", "rule": "区分依据为分类维度：本节点按“船体结构”划分（如双体、多体）；兄弟节点按“材料”划分（如钢、木）。"}, {"other_code": "N_24f79f9d6d4ff534", "rule": "区分依据为分类维度：本节点按“船体结构”划分；兄弟节点按“航行状态”划分（如气垫、水翼）。"}], "cross_boundary_rule": "若内容涉及特定结构的船舶（如双体客船），主挂载本节点；若侧重其载客功能，可关联“运输船”，但主挂载依据结构特征归本节点。"}]}
